parameters.functionCode:
let transcript;
let meetingTitle = $json.meetingTitle || "Untitled Meeting";
let meetingDate = $json.meetingDate || new Date().toISOString().split('T')[0];
let attendees = $json.attendees || [];

if ($node["Webhook (Manual Upload)"].json.transcript) {
  transcript = $node["Webhook (Manual Upload)"].json.transcript;
} else if ($node["Google Drive - Download Transcript"].binary && $node["Google Drive - Download Transcript"].binary.data) {
  transcript = Buffer.from($node["Google Drive - Download Transcript"].binary.data.data, 'base64').toString('utf8');
}

// Extract emails from transcript
const emailRegex = /[\w.-]+@[\w.-]+\.[A-Za-z]{2,}/g;
const foundEmails = transcript.match(emailRegex) || [];

attendees = [...new Set([...attendees, ...foundEmails])];

return [{ json: { transcript, meetingTitle, meetingDate, attendees } }];

parameters.body:
={{`Hi Team,

Here’s the summary for ${$json.meetingTitle} on ${$json.meetingDate}:

${$json.minutes}

Google Doc: ${$node["Google Docs - Create"].json.url}`}}

={
  "summary": "{{$json.meetingTitle}}",
  "description": "Meeting scheduled with attached minutes.",
  "start": { "dateTime": "{{$json.meetingDate}}T09:00:00Z", "timeZone": "Asia/Kolkata" },
  "end": { "dateTime": "{{$json.meetingDate}}T10:00:00Z", "timeZone": "Asia/Kolkata" },
  "attendees": {{$json.attendees.map(email => ({ "email": email }))}},
  "attachments": [
    { "fileUrl": "{{$node["Google Docs - Create"].json.webViewLink}}", "title": "Meeting Minutes" }
  ]
}
